16	        for (int pass = 0; pass < n - 1; pass++) {
17	            boolean swapped = false;
18	
19	            for (int index = 0; index < n - pass - 1; index++) {
20	                if (isOutOfOrder(values[index], values[index + 1])) {
21	                    swap(values, index, index + 1);
22	                    swapped = true;
23	                }
24	            }
25	
26	            if (!swapped) {
27	                break;
28	            }
29	        }
30	    }
